fn prim_box(p: vec3<f32>, size: vec3<f32>) -> f32 {
    let q = abs(p) - size;
    let max_q = max(q.x, max(q.y, q.z));
    let clamped = max(q, vec3<f32>(0.0));
    let squared = dot(clamped, clamped);
    if (max_q <= 0.0) { return max_q; }
    return sqrt(squared);
}

