fn prim_cylinder(p: vec3<f32>, radius: f32, height: f32) -> f32 {
    let d_xy = sqrt(p.x * p.x + p.y * p.y + 1e-20) - radius;
    let d_z = abs(p.z) - height;
    let max_d = max(d_xy, d_z);
    if (max_d <= 0.0) { return max_d; }
    let a = max(d_xy, 0.0);
    let b = max(d_z, 0.0);
    return sqrt(a * a + b * b);
}

