fn rotate_about(p: vec3<f32>, origin: vec3<f32>, axis: vec3<f32>, angle: f32) -> vec3<f32> {
    let v = p - origin;
    let c = cos(angle);
    let s = sin(angle);
    let parallel = axis * dot(v, axis);
    return origin + v * c + cross(axis, v) * s + parallel * (1.0 - c);
}

